insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('2efecf97-4c19-5e74-bbef-707e2cef5285', 'T01', '銀座のおもてなし職人', '気づかれないほど自然な気配りが、最高のサービス。', 'あなたは、お客様がまだ言葉にしていない「本当はこうしてほしい」を、表情のわずかな変化や間合いから読み取り、頼まれる前にそっと整えてしまうタイプです。声高に接客をアピールするのではなく、動線を整え、温度を整え、間を整えることで、お客様が『なぜだか居心地がいい』と感じる時間そのものをつくり出します。目立つことより、自分が動いた後に店の空気が静かに良くなっている瞬間に、何よりの手応えを感じる人。派手さはなくても、一度その接客を受けたお客様は、次も必ずあなたを指名したくなります。', 'Hospitality Stars', 'H01 銀座の黒子', '{"先読み","落ち着き","高い接客基準"}', '{"自己犠牲になりやすい","成果が見えにくい"}', '{"高級店サービス","ホテルサービス","コンシェルジュ"}', '{"鮨","割烹","フレンチ","会員制"}', '{"シニアサービス","副支配人候補"}', 'Guest', 'Craft', 'High-end', 'Specialist', 'Arrange', 'Intuitive', '/characters/T01.webp', '相手の些細な変化を察知することに強い喜びを感じるタイプです。目立つことより、場の空気や体験全体を滑らかにすることに価値を置き、自分の手柄よりも「相手が心地よかったかどうか」を判断基準にします。感覚的な間合いのつかみ方に長け、マニュアル以上の気配りを自然に行えるのが最大の武器です。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('27c1b7be-4235-5d37-af85-a48165f34686', 'T02', 'サービス分析官', 'おもてなしを、感覚だけで終わらせない。', 'あなたは「なぜあの接客はお客様に響いたのか」を、感覚のままにせず、行動や数字の裏付けをもって説明できる人です。良い接客エピソードを聞いても「素晴らしいですね」で終わらせず、「それを誰でも再現できる形にするには?」と考え始めます。感情に流されず、事実に基づいて冷静に状況を捉える力があるからこそ、属人的になりがちなホスピタリティの世界に、再現性という新しい価値をもたらせる稀有な存在です。', 'Hospitality Stars', 'H01 銀座の黒子', '{"観察力","改善力","再現性"}', '{"数字に寄りすぎる","現場の温度感を失いやすい"}', '{"CX改善","サービス品質管理","研修企画"}', '{"ホテル","高級レストラン","大型店"}', '{"サービス企画","品質責任者"}', 'Guest', 'Craft', 'High-end', 'Specialist', 'Arrange', 'Data', '/characters/T02.webp', '感覚と経験だけに頼らず、「なぜうまくいったのか」を言語化し、誰でも再現できる形にすることに価値を感じるタイプです。感情に流されず、事実に基づいて冷静に状況を捉える力があり、周囲が浮足立つ場面でも一歩引いて全体を観察できます。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('05507a6b-6bc7-5ef8-a004-043ccafbbcf7', 'T03', '接客革命家', '『普通の接客』を、もっと面白く。', 'あなたは「接客とはこういうものだ」という既存の枠組みを、そのまま受け入れることができないタイプです。決まった台詞、決まった動線、決まった距離感——それらが悪いわけではないと分かっていても、心のどこかで「もっと面白くできるはずだ」とうずうずしてしまいます。思いついたアイデアは頭の中で完成させるより先に、まず現場で試してしまう。そのフットワークの軽さと発想力が、他の誰にも真似できない体験をお客様に届けます。', 'Hospitality Stars', 'H03 空気の演出家', '{"発想力","行動力","顧客理解"}', '{"やりすぎて好みが分かれる","標準化が弱い"}', '{"体験企画","イベント接客","SNS連動企画"}', '{"エンタメレストラン","カフェ","バー"}', '{"CX企画","新店立ち上げ"}', 'Guest', 'Craft', 'High-end', 'Specialist', 'Venture', 'Intuitive', '/characters/T03.webp', '『普通』に飽き足らず、既存の接客の枠を超えた体験を作ることに情熱を燃やすタイプです。発想力と行動力があり、思いついたらまず試してみる直感型で、頭で完璧に計画を練り上げるより、現場で反応を見ながら調整していくスタイルを好みます。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('d4966310-492f-547e-8f82-549fab177b7c', 'T04', 'CXストラテジスト', '顧客体験を、事業の成長エンジンに。', 'あなたは、一回一回の接客という「点」ではなく、お客様が来店を決めた瞬間から、食事を終えて次の来店を考えるまでの「線」全体を設計しようとするタイプです。感覚的な良い接客が偶然の産物にならないよう、来店動機、期待値、体験の流れ、そして再来店の理由までを一つの物語として組み立てます。現場の熱量とデータの両方を武器に、顧客体験を事業の成長エンジンへと変えていく戦略家です。', 'Hospitality Stars', 'B01 ブランド創造者', '{"顧客設計","ブランド視点","分析力"}', '{"現場負荷を見落としやすい","設計が複雑化しやすい"}', '{"CX責任者","ブランド企画","CRM"}', '{"高級業態","ホテル","複合施設"}', '{"CX責任者","事業企画"}', 'Guest', 'Craft', 'High-end', 'Specialist', 'Venture', 'Data', '/characters/T04.webp', '一つひとつの接客だけでなく、来店前から退店後までの体験全体を設計することに関心を持つ戦略家タイプです。感覚ではなくデータと論理で顧客体験を組み立てるため、感情的な議論が続く場でも「そもそも何を目指しているのか」という視点を提示できます。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('441278c2-75b0-5f74-be5c-dfc90aa01603', 'T05', '銀座支配人', '一人のお客様と、店全体を同時に見る。', 'あなたは、目の前の一人のお客様に丁寧に向き合いながら、同時に店全体の空気を見渡すという、一見矛盾する二つの視点を自然に両立できる人です。自ら接客の最前線に立って模範を示しながら、チーム全体を動かしていく現場リーダー。「この人がいれば大丈夫」という安心感を、スタッフにもお客様にも同時に与えられる、店の中心となる存在です。', 'Hospitality Stars', 'L01 現場司令官', '{"統率力","顧客対応","危機管理"}', '{"抱え込みやすい","部下に高基準を求めすぎる"}', '{"支配人","サービスマネージャー"}', '{"高級店","ホテル","会員制"}', '{"支配人","店舗責任者"}', 'Guest', 'Craft', 'High-end', 'Leader', 'Arrange', 'Intuitive', '/characters/T05.webp', '一人のお客様への丁寧な対応と、店全体を見渡す視野を同時に持つ現場リーダータイプです。自らが接客の模範を示しながら、チームを引っ張ります。目の前の一卓に集中しているように見えて、実は店内全体の状況を常に把握しているという、高度な並行処理能力を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('dbb9f32c-5287-5857-b4b9-bc35dd5b6c90', 'T06', 'ラグジュアリー統括官', '上質さを、複数店舗で再現する。', 'あなたは、一店舗だけの奇跡的な成功に満足せず、それを「どの店舗でも再現できる基準」に変えることに強い使命感を持つタイプです。感覚に頼った属人的なサービスではなく、教育・監査・仕組みという確かな土台の上に、上質さを積み上げていきます。一店舗のカリスマではなく、複数店舗、時にはブランド全体の品質を静かに底上げしていく縁の下の力持ちです。', 'Hospitality Stars', 'L04 改善プロデューサー', '{"標準化","教育","多店舗管理"}', '{"現場との距離が開きやすい","ルール過多になりやすい"}', '{"サービス統括","教育責任者","SV"}', '{"ホテル","高級チェーン","百貨店"}', '{"統括責任者","SV"}', 'Guest', 'Craft', 'High-end', 'Leader', 'Arrange', 'Data', '/characters/T06.webp', '一店舗の成功体験を、仕組みとして複数店舗に広げることに使命感を持つタイプです。感覚に頼らず、基準・教育・監査という形で品質を再現しようとします。優れた店舗や優れたスタッフを見たとき、多くの人が「すごいですね」で終わるところを、あなたは「これはなぜ再現できているのか、他の店でもできるようにするには何が必要か」を考え始めます。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('c09c387a-b67a-59da-a08f-d3e7668f2354', 'T07', 'ホスピタリティ開拓者', 'まだない『喜ばせ方』をつくる。', 'あなたは、前例がないという状況を怖がるどころか、むしろ心が躍るタイプです。マニュアルもなく、正解も誰も知らない土地や新しい業態でも、「人を喜ばせる方法はきっとある」と信じ、現場に飛び込んで自分の力で見つけ出します。文化や言葉の壁があっても、初日から常連さんのように馴染んでしまう適応力と共感力こそが、あなたの最大の武器です。', 'Hospitality Stars', 'G01 挑戦者', '{"適応力","共感力","挑戦心"}', '{"準備不足","再現性が弱い"}', '{"新店立ち上げ","海外店","イベント"}', '{"新業態","観光地","海外"}', '{"立ち上げメンバー","サービス責任者"}', 'Guest', 'Craft', 'High-end', 'Leader', 'Venture', 'Intuitive', '/characters/T07.webp', '未知の環境でも『人を喜ばせる方法』を自分の力で見つけ出せるタイプです。前例のない状況に対する適応力と、現場に飛び込む行動力を兼ね備えています。多くの人が「マニュアルがないと不安」と感じる場面で、あなたはむしろ「自分のやり方を確立できる」とワクワクします。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('d21e7413-df73-5200-8830-25970f623753', 'T08', 'ホスピタリティCEO', '人を喜ばせる文化を、会社の競争力に。', 'あなたは、一回の食事や一人の接客という単位ではなく、顧客・従業員・ブランドという三つの要素を一つの物語として捉える、経営者の視座を持つタイプです。ホスピタリティを単なる「良いサービス」で終わらせず、会社全体の競争力そのものへと変えようとします。目先の利益より、長期的に愛され続ける文化を作ることに、静かな、しかし強い情熱を注いでいます。', 'Hospitality Stars', 'B05 食文化プロデューサー', '{"経営視点","文化づくり","長期設計"}', '{"理想が大きくなりやすい","現場の細部を見失いやすい"}', '{"経営者","ブランドCEO","事業責任者"}', '{"高級グループ","ホテル","複数ブランド"}', '{"CEO","事業本部長"}', 'Guest', 'Craft', 'High-end', 'Leader', 'Venture', 'Data', '/characters/T08.webp', '顧客・従業員・ブランドを一つの物語として捉え、ホスピタリティを会社全体の競争力に変えようとする経営者気質です。長期的な視点で文化を作ることに情熱を注ぎます。現場の小さな一場面を見ても、そこから「この会社は何を大切にしているのか」という大きな問いへと思考を広げていく癖があります。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('9637d169-29cf-5d44-a066-cae4768094f6', 'T09', '愛されホールスタッフ', '名前を覚えられるより、相手を覚えている。', 'あなたにとって接客とは、業務ではなく「関係づくり」そのものです。お客様の名前や肩書きよりも、その人がどんな一日を過ごしてきたか、今日はどんな気分かということに自然と意識が向きます。飾らない親しみやすさで距離を縮め、「またあの人に会いたいから、あの店に行こう」と思わせる。特別な演出をしなくても、あなたがそこにいるだけで、その場所は誰かの「行きつけ」になっていきます。', 'Community Hosts', 'H05 常連メーカー', '{"親近感","関係構築","会話力"}', '{"常連を優先しすぎる","距離が近くなりすぎる"}', '{"ホール","カフェスタッフ","居酒屋接客"}', '{"居酒屋","カフェ","地域店"}', '{"ホールリーダー"}', 'Guest', 'Craft', 'Mass', 'Specialist', 'Arrange', 'Intuitive', '/characters/T09.webp', '肩書きより、お客様一人ひとりとの関係そのものを大切にするタイプです。名前や役職を覚えられることより、『あの人が来た』と自分が気づけることに喜びを感じます。飾らない親しみやすさが自然な魅力になっており、初対面のお客様とも数回のやり取りで、まるで長年の顔なじみのような空気を作り出せます。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('ada9def9-02f2-5505-ab89-ce783267aba9', 'T10', '接客オペレーター', '忙しくても、誰にでも心地よい接客を。', 'あなたは、忙しさの中でこそ「誰が担当しても同じ心地よさを届ける」という理想を追い求めるタイプです。感覚的な接客の良し悪しではなく、誰もが実践できる「型」として接客を捉え、行列や満席の状況でも一定のクオリティを崩しません。派手さはなくとも、あなたが整えた仕組みは、店全体の安定感という形で確実にお客様の満足を支えています。', 'Community Hosts', 'C04 再現の達人', '{"安定運営","効率","接客基準"}', '{"個別対応が弱くなりやすい","柔軟性不足"}', '{"接客トレーナー","オペレーション"}', '{"ファミレス","フードコート","チェーン"}', '{"トレーナー","時間帯責任者"}', 'Guest', 'Craft', 'Mass', 'Specialist', 'Arrange', 'Data', '/characters/T10.webp', '誰が担当しても同じ心地よさを届けられる状態を目指すタイプです。忙しさの中でも一定の品質を保つことに誇りを持ち、感覚ではなく型として接客を捉えます。多くの人が「忙しいから仕方ない」と品質のブレを許容してしまう場面でも、あなたは「型さえあれば、忙しくても崩れないはずだ」と考え、改善の余地を探し続けます。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('830a1cab-ba59-5219-823f-2892bdf6f4c3', 'T11', '地域の人気者', '店を、街の居場所に変える。', 'あなたにとって、お店とは単なる飲食の場ではなく、人が自然と集まる「街の居場所」です。売上や効率よりも先に、「この街にとってこの店がどんな存在でありたいか」という問いが頭に浮かびます。地域のお祭りやイベントには自然と店を絡めたくなり、常連さん同士を紹介せずにはいられない。あなたが働く店は、いつしか単なる飲食店を超えて、地域のコミュニティの一部になっていきます。', 'Community Hosts', 'H05 常連メーカー', '{"人脈","親しみ","発信力"}', '{"内輪感が出やすい","採算管理が甘くなりやすい"}', '{"地域店スタッフ","コミュニティ運営"}', '{"町中華","カフェ","居酒屋"}', '{"店長候補","コミュニティ担当"}', 'Guest', 'Craft', 'Mass', 'Specialist', 'Venture', 'Intuitive', '/characters/T11.webp', '店を単なる飲食の場ではなく、人が集まる『居場所』にしたいと考えるタイプです。地域の人々との関係を育てることに情熱を注ぎ、自然と発信力も発揮します。お客様同士のつながりを作ることにも積極的で、初対面同士のお客様を自然に会話に巻き込んでしまうような場面も少なくないでしょう。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('dbbceb4e-9eca-502d-aaac-b89435ad9350', 'T12', '繁盛店マーケター', '『また来たい』を、数字で増やす。', 'あなたは、「お客様がまた来たいと思う理由」を、感覚的な良し悪しではなく、データという確かな手がかりから見つけ出そうとするタイプです。リピート率の数字が上がった瞬間に静かにガッツポーズをし、SNSの反応から次の一手のヒントを探る。現場の温度感と数字の両方を大切にしながら、「なんとなく良い接客」を「確実に効果のある施策」へと変えていく仕掛け人です。', 'Community Hosts', 'B04 数字の戦略家', '{"分析力","販促","顧客理解"}', '{"短期施策に偏りやすい","現場負荷を増やしやすい"}', '{"店舗マーケティング","CRM","販促"}', '{"大衆店","チェーン","カフェ"}', '{"販促責任者","マーケ担当"}', 'Guest', 'Craft', 'Mass', 'Specialist', 'Venture', 'Data', '/characters/T12.webp', 'お客様の『また来たい』という気持ちを、感覚ではなく数字で捉え、増やしていくことに面白さを感じるタイプです。現場の反応とデータの両方を大切にします。SNSの投稿への反応、リピート率の推移、客単価の変化といった数字の裏に、必ずお客様の生きた感情があると信じており、その両方を行き来しながら仮説を立てるのが得意です。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('78ad60ad-61c1-56b8-b22c-d1d0f4f68ba8', 'T13', '愛され店長', 'スタッフにもお客様にも、会いに来てもらえる店長。', 'あなたは、お客様だけでなく、一緒に働くスタッフからも「会いに来たくなる」と思われる稀有な人柄の持ち主です。厳しく指示を出すよりも、親しみやすさと調整力で、自然と人が定着していく空気を作り出します。辞めていったスタッフが「また働きたい」と戻ってくる。それは偶然ではなく、あなたという店長が作り出す、居心地の良さの証明です。', 'Community Hosts', 'L03 チームビルダー', '{"信頼構築","育成","接客"}', '{"厳しい判断を避けやすい","人に頼られすぎる"}', '{"店長","カフェマネージャー","居酒屋店長"}', '{"地域店","カフェ","居酒屋"}', '{"店長","エリア店長候補"}', 'Guest', 'Craft', 'Mass', 'Leader', 'Arrange', 'Intuitive', '/characters/T13.webp', 'スタッフにもお客様にも『会いに来たくなる』と思わせる人柄を持つタイプです。親しみやすさと調整力で、人が自然と定着する空気をつくります。強いカリスマ性で人を引っ張るというより、一人ひとりの話をよく聞き、それぞれが働きやすい環境を丁寧に整えていくタイプのリーダーです。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('9fe87d17-9264-54ca-b954-264ce50707fa', 'T14', '繁盛店司令官', 'ピークの混乱を、売上に変える。', 'あなたは、混雑や忙しさをストレスではなく、エネルギーに変えられる稀有なタイプです。満席の店内、鳴り止まないオーダー、ざわめく空気——それらが強まるほど、頭が冴え、視界がクリアになっていきます。人・席・商品を的確に動かし、活気と効率を両立させる。ピークタイムという修羅場は、あなたにとって最も輝ける舞台です。', 'Community Hosts', 'L01 現場司令官', '{"即断力","配置力","現場統率"}', '{"指示が強くなりやすい","長期育成が後回し"}', '{"店長","大型店責任者"}', '{"居酒屋","焼肉","繁盛大衆店"}', '{"店長","SV候補"}', 'Guest', 'Craft', 'Mass', 'Leader', 'Arrange', 'Data', '/characters/T14.webp', '混雑や忙しさをむしろエネルギーに変えられるタイプです。ピークタイムの現場で人・席・商品を的確に動かし、活気と効率を両立させることに手応えを感じます。多くの人が焦りでパニックになりそうな満席の状況でも、あなたは不思議と落ち着き、「何番テーブルが空くか」「誰にどの仕事を振るか」が瞬時に頭の中で組み上がっていきます。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('27a87b9c-e5dc-5b0c-bf79-627925d51d4c', 'T15', 'コミュニティ創業者', '好きな人が集まる場所を、自分でつくる。', 'あなたは、自分の好きなものや大切にしたい価値観を軸に、人が集まる場所を自分の手で作り出したいと願うタイプです。誰かに雇われて働くことよりも、「こんな店があったらいいな」という理想を、実際に自分の手で形にしてしまう。強い独立心と発信力を武器に、単なる飲食店ではなく、共感で結ばれた濃いコミュニティを育てていきます。', 'Community Hosts', 'B02 未来のオーナー', '{"コミュニティ","独立心","発信力"}', '{"内輪化","事業規模を広げにくい"}', '{"独立店主","コミュニティカフェ"}', '{"カフェ","バー","地域店"}', '{"オーナー","ブランド発起人"}', 'Guest', 'Craft', 'Mass', 'Leader', 'Venture', 'Intuitive', '/characters/T15.webp', '自分の好きなものや大切にしたい価値観を軸に、人が集まる場所を自分の手でつくりたいと考えるタイプです。独立心と発信力を併せ持ちます。誰かの店で働きながらも、頭の中には常に「自分ならこうする」という理想の店の姿が描かれており、その理想を実現したいという気持ちを抑えきれません。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('fa66aa2c-6707-5efd-847b-768c1604d25a', 'T16', '大衆店プロデューサー', '親しみやすさを、強い業態にする。', 'あなたは、「親しみやすさ」という感覚的な価値を、誰もが日常的に選びたくなる強い業態として設計することに関心を持つタイプです。一店舗の繁盛だけでなく、その仕組みを他の街でも展開できないかと、常に事業としてのスケールを見据えています。温かみと収益性、この両立が難しいテーマに、正面から挑む設計者です。', 'Community Hosts', 'L05 繁盛店メーカー', '{"業態設計","収益力","現場理解"}', '{"効率優先になりやすい","個性が薄くなりやすい"}', '{"業態開発","事業責任者","FC本部"}', '{"大衆業態","チェーン"}', '{"事業責任者","ブランド統括"}', 'Guest', 'Craft', 'Mass', 'Leader', 'Venture', 'Data', '/characters/T16.webp', '親しみやすさという感覚的な価値を、誰もが日常的に選びたくなる『強い業態』として設計することに関心を持つタイプです。事業としてのスケールを見据えています。繁盛している店を見ると、単に「良いお店だな」で終わらせず、「なぜこの店は繁盛しているのか、他の街でも再現できるか」を無意識に分析してしまいます。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('b04b6d07-5120-5221-bb27-1bd33e5f0a3a', 'T17', '高級店セールス職人', '売るのではなく、価値を理解して選んでもらう。', 'あなたは、「売る」という行為に抵抗を感じる不思議な営業職です。押し売りではなく、お客様がまだ気づいていない価値を丁寧に伝え、「理解した上で選んでもらう」ことにこだわります。専門知識という武器を、知識自慢のためではなく、目の前の人にぴったりの一本、一皿を選び当てるために使う。信頼を積み重ねることに時間をかけられる、静かな職人気質の持ち主です。', 'Luxury Leaders', 'H04 ワインの語り部', '{"提案力","専門知識","信頼構築"}', '{"説明過多","数字目標で接客が硬くなる"}', '{"ソムリエ","高級販売","予約担当"}', '{"高級鮨","ワインバー","ホテル"}', '{"シニアサービス","セールス担当"}', 'Guest', 'Business', 'High-end', 'Specialist', 'Arrange', 'Intuitive', '/characters/T17.webp', '『売る』のではなく『理解して選んでもらう』ことにこだわるタイプです。専門知識を武器に、お客様がまだ気づいていない価値を丁寧に伝えます。信頼を積み重ねることに時間をかけられるのが特徴で、目先の一回の会計よりも、長期的な信頼関係を優先する判断を自然に下せます。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('899d0394-15cb-54db-a6c7-f3e49a3b8b36', 'T18', 'ラグジュアリー収益分析官', '上質さを守りながら、利益を残す。', 'あなたは、「上質さ」と「利益」という、しばしば対立しがちな二つの価値を、どちらも諦めずに両立させることに使命感を持つタイプです。憧れや高級感といった感覚的な魅力を、客単価や稼働率という具体的な数字に翻訳し、事業として持続可能な形に整えていきます。感性と論理、両方を武器に戦える希少な人材です。', 'Luxury Leaders', 'B04 数字の戦略家', '{"収益分析","価格設計","計画性"}', '{"現場感を失いやすい","ブランド価値を数字化しすぎる"}', '{"収益管理","レベニューマネジメント"}', '{"ホテル","高級店"}', '{"収益責任者","管理責任者"}', 'Guest', 'Business', 'High-end', 'Specialist', 'Arrange', 'Data', '/characters/T18.webp', '上質さと利益、どちらも諦めずに両立させることに使命感を持つタイプです。感覚的な高級感を、客単価や稼働率といった具体的な数字で裏付けて捉えます。多くの人が「高級だから利益が出て当然」と考えがちな中で、あなたは高級業態こそ繊細な収益構造の上に成り立っていることを深く理解しています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('e5aec57b-b552-5324-adcf-5f7b592544c8', 'T19', '高級ブランド仕掛け人', '憧れられる店には、理由がある。', 'あなたは、「憧れられる店には理由がある」という確固たる信念を持ち、料理・空間・物語を一つのブランドとして丁寧に編み上げていくタイプです。美意識と発信力を武器に、単なる美味しい店ではなく、「選ばれる理由」を持つ店を作り出します。写真映えよりも、体験として長く語り継がれる瞬間を作りたいと願う、静かな情熱の持ち主です。', 'Luxury Leaders', 'B01 ブランド創造者', '{"ブランド設計","美意識","発信力"}', '{"現場との乖離","外見優先になりやすい"}', '{"ブランド企画","PR","クリエイティブ"}', '{"高級店","ホテル","会員制"}', '{"ブランドマネージャー"}', 'Guest', 'Business', 'High-end', 'Specialist', 'Venture', 'Intuitive', '/characters/T19.webp', '『憧れられる店には理由がある』という信念を持ち、料理・空間・物語を一つのブランドとして編み上げるタイプです。美意識と発信力を武器にします。店の内装や器を見るだけで、その裏にあるストーリーを考えずにはいられない、根っからの物語思考の持ち主です。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('9760649d-054e-575c-b496-bea25a4139fb', 'T20', 'ラグジュアリー戦略家', '一店舗の名声を、持続する事業へ。', 'あなたは、一店舗の名声という一過性の輝きを、持続する事業として育てたいと願う戦略家です。ブランド資産、市場動向、顧客データを俯瞰しながら、「このブランドは5年後どうなっているか」を常に思い描いています。目先の評判に一喜一憂せず、長期的な視点で高級事業の成長戦略を静かに描き続ける人です。', 'Luxury Leaders', 'B01 ブランド創造者', '{"戦略設計","市場分析","長期視点"}', '{"現場実装が遅い","理論先行"}', '{"経営企画","ブランド戦略","投資企画"}', '{"高級グループ","ホテル"}', '{"戦略責任者","経営企画"}', 'Guest', 'Business', 'High-end', 'Specialist', 'Venture', 'Data', '/characters/T20.webp', '一店舗の名声を、一過性で終わらせず持続する事業として育てたいと考える戦略家です。ブランド資産や市場を俯瞰する長期的な視点を持っています。話題の高級店を見かけても、単に「良い店だ」で終わらせず、その成長戦略や今後の展開可能性まで分析してしまう癖があるでしょう。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('fcd57349-9ee1-5dc7-ad63-a59034038321', 'T21', 'ブランド支配人', '店の世界観を、人と現場で守り抜く。', 'あなたは、店の世界観やブランドの基準を、顧客対応と組織運営の両面から守り抜く、強い責任感の持ち主です。お客様の期待値を上回る瞬間に最大のやりがいを感じながら、同時にスタッフが働きやすい環境を整えることにも心を配ります。ブランドらしさを、言葉にせずとも体現できる、まさに「顔」となる存在です。', 'Luxury Leaders', 'L01 現場司令官', '{"ブランド理解","統率","顧客対応"}', '{"基準が厳しくなりすぎる","現場負担増"}', '{"支配人","GM"}', '{"高級レストラン","ホテル"}', '{"支配人","GM"}', 'Guest', 'Business', 'High-end', 'Leader', 'Arrange', 'Intuitive', '/characters/T21.webp', '店の世界観やブランドの基準を、人と現場の両面から守り抜く責任感の強いタイプです。顧客対応と組織運営、どちらも自分の役割だと捉えます。店の細部にわずかな乱れがあれば、誰よりも早く気づき、すぐに正そうとする強いこだわりを持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('9353f673-bd9f-5ddd-9b0b-e340821c2a98', 'T22', '高級業態COO', 'ブランドの輝きを、強い運営に変える。', 'あなたは、ブランドの輝きを感覚的な魅力だけで終わらせず、強い運営の仕組みへと変えていきたいと考えるタイプです。品質を守りながら、組織、数値、出店計画までを一貫して管理する実行力を持ちます。複数店舗の数字を並べて比較するのが日課になっているほど、事業全体を俯瞰する視座の高さが、あなたの最大の武器です。', 'Luxury Leaders', 'L05 繁盛店メーカー', '{"事業運営","組織統括","品質管理"}', '{"管理過多","現場との距離"}', '{"COO","事業部長","統括"}', '{"高級多店舗","ホテル"}', '{"COO","事業本部長"}', 'Guest', 'Business', 'High-end', 'Leader', 'Arrange', 'Data', '/characters/T22.webp', 'ブランドの輝きを、感覚だけでなく強い運営の仕組みに変えたいと考えるタイプです。品質を守りながら、組織・数値・出店計画までを管理する実行力を持ちます。品質のブレを見つけると、その原因を突き止めずにはいられない、根っからの改善志向の持ち主です。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('3fd6e051-af35-5586-ae8c-02219b432c14', 'T23', 'ラグジュアリー起業家', '自分の美学を、選ばれるブランドに。', 'あなたは、自分自身の美学や価値観を、誰かに選ばれるブランドという形にしたいと願う、起業家気質の持ち主です。強い世界観を持ちながらも、それを独りよがりにせず、顧客が本当に求めているものを見抜く目も併せ持っています。内装や器、一つひとつに妥協できないこだわりこそが、あなたのブランドを唯一無二のものにしていきます。', 'Luxury Leaders', 'B02 未来のオーナー', '{"独立心","審美眼","顧客設計"}', '{"初期投資が大きい","自分の感性へ依存"}', '{"高級店オーナー","ブランド創業者"}', '{"鮨","割烹","会員制"}', '{"創業者","オーナーシェフ"}', 'Guest', 'Business', 'High-end', 'Leader', 'Venture', 'Intuitive', '/characters/T23.webp', '自分の美学や価値観を、選ばれるブランドという形にしたいと考える起業家気質です。強い世界観と、顧客の求めるものを見抜く目を併せ持っています。『こんな店があったら通いたい』という理想を、頭の中で完結させず、実際に作ってしまう行動力の持ち主です。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('872b51a2-56bc-5752-b6aa-58a8bd059b9f', 'T24', '高級外食CEO', '食の憧れを、企業価値へ。', 'あなたは、食への憧れを一つの店にとどめず、企業としての価値にまで育て上げたいと願う、スケールの大きな経営者気質の持ち主です。資本、人材、海外展開まで見据えた大きな視座で、一つの成功店をグループ全体の資産へと発展させていきます。海外の高級ブランド事例を研究するのが習慣になっているほど、常に世界水準の視点を持ち続けています。', 'Luxury Leaders', 'B05 食文化プロデューサー', '{"経営力","ブランド群管理","長期成長"}', '{"現場解像度の低下","拡大優先"}', '{"CEO","投資責任者","グループ経営"}', '{"高級ブランド群"}', '{"CEO","代表取締役"}', 'Guest', 'Business', 'High-end', 'Leader', 'Venture', 'Data', '/characters/T24.webp', '食への憧れを、一つの店にとどめず企業としての価値にまで育てたいと考える経営者気質です。資本・人材・海外展開まで見据えた大きな視座を持っています。一つの成功店を見ると、単なる繁盛店としてではなく、グループ展開の可能性まで考えてしまう、スケールの大きな思考の持ち主です。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('3c99c2f3-6722-5688-bbe1-5bcdb293464b', 'T25', '売上アップ職人', '現場の小さな工夫で、数字を動かす。', 'あなたは、大きな戦略よりも、現場で今日から実行できる小さな工夫を積み重ねることに手応えを感じるタイプです。商品の陳列を少し変えただけで売上が動く瞬間に喜びを覚え、「なぜあの店は繁盛しているのか」を観察せずにはいられません。地に足のついた改善の積み重ねが、いつの間にか大きな数字になっていく。それを誰よりも知っている、現場発の改善職人です。', 'Scale Builders', 'L04 改善プロデューサー', '{"改善力","実行力","売上感覚"}', '{"局所最適","施策疲れ"}', '{"店舗改善","販促","店長補佐"}', '{"チェーン","大衆店"}', '{"改善担当","副店長"}', 'Guest', 'Business', 'Mass', 'Specialist', 'Arrange', 'Intuitive', '/characters/T25.webp', '大きな戦略より、現場で今日から実行できる小さな工夫を積み重ねることに手応えを感じるタイプです。商品配置や声かけなど、地に足のついた改善を好みます。壮大な経営理論よりも、「今日、この店でできることは何か」という具体的な問いに向き合うことに、強いやりがいを感じます。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('e0d27274-3d45-5b5a-8ffa-f4ea57a43afe', 'T26', '店舗利益分析官', '店の数字から、ムダと伸びしろを見つける。', 'あなたは、店の数字の中に隠れたムダと伸びしろを見つけることに、知的な面白さを感じるタイプです。感覚ではなく、原価や人件費といった具体的なデータをもとに、冷静に判断を下していきます。商品別の利益率を見ると、つい頭の中で並べ替えてしまう。数字の改善に、地味ながらも一番のやりがいを感じる分析家です。', 'Scale Builders', 'B04 数字の戦略家', '{"分析力","利益管理","計画性"}', '{"現場の納得感不足","短期数字偏重"}', '{"管理会計","店舗分析","SV支援"}', '{"チェーン","多店舗"}', '{"分析担当","管理責任者"}', 'Guest', 'Business', 'Mass', 'Specialist', 'Arrange', 'Data', '/characters/T26.webp', '店の数字の中に隠れたムダと伸びしろを見つけることに知的な面白さを感じるタイプです。感覚ではなく、原価や人件費といった具体的なデータで判断します。「このメニュー、実は儲かっていない」という発見に気づく瞬間に、他の人にはない独特の高揚感を覚えます。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('a88883e7-4650-56ac-ac42-9aa8dc5022ef', 'T27', 'ヒット業態ハンター', '次に伸びる店の型を、誰より早く見つける。', 'あなたは、次に伸びる業態やメニューの気配を、誰よりも早く察知することに長けたタイプです。トレンドと顧客ニーズへの感度が高く、思いついたらすぐ試したくなる。話題の店を見つけると、すぐ食べに行って分析したくなる。『これ、次来る』という直感がよく当たる、市場の嗅覚を持ったハンターです。', 'Scale Builders', 'B03 新業態クリエイター', '{"市場感覚","企画力","スピード"}', '{"流行追随","検証不足"}', '{"業態開発","市場調査","新店企画"}', '{"新業態","ポップアップ"}', '{"企画担当","開発責任者"}', 'Guest', 'Business', 'Mass', 'Specialist', 'Venture', 'Intuitive', '/characters/T27.webp', '次に伸びる業態やメニューの気配を、誰よりも早く察知することに長けたタイプです。トレンドと顧客ニーズへの感度が高く、思いついたらすぐ試したくなります。新しいアイデアを思いつくと、いてもたってもいられなくなるほど、行動力とスピード感が持ち味です。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('c7c624c3-c54b-58d0-b762-c55e70fa1863', 'T28', 'フードテック戦略家', 'テクノロジーで、店舗経営を軽く強く。', 'あなたは、テクノロジーの力で店舗経営をより軽く、より強くすることに情熱を注ぐタイプです。データやツールを使って、感覚だけに頼らない経営を実現しようとします。新しいPOSシステムやモバイルオーダーの話を聞くとワクワクし、『このデータ、もっと活用できるのでは』が口癖になっている、現場のデジタル化を推進する変革者です。', 'Scale Builders', 'G04 変革者', '{"DX","戦略","分析力"}', '{"現場適合不足","ツール先行"}', '{"DX企画","プロダクト企画"}', '{"チェーン","デリバリー"}', '{"DX責任者","企画責任者"}', 'Guest', 'Business', 'Mass', 'Specialist', 'Venture', 'Data', '/characters/T28.webp', 'テクノロジーの力で店舗経営をより軽く、強くすることに情熱を注ぐタイプです。データやツールを使って、感覚だけに頼らない経営を実現しようとします。手作業のオペレーションを見ると、自動化できないか考えてしまうほど、テクノロジーによる改善の可能性を常に探し続けています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('d3016d2f-fa55-5ba9-bd11-323cdd8fedd5', 'T29', '現場司令官', 'ピークの5分で、店の実力が出る。', 'あなたは、ピークタイムの5分間にこそ、その店の本当の実力が出ると考えるタイプです。繁忙時ほど頭が冴え、全体を見渡して即座に判断を下せます。満席の店内でも、誰が何をすべきか瞬時に見えている。『大丈夫、いける』と自分にもチームにも言い聞かせられる、修羅場に強い現場司令官です。', 'Scale Builders', 'L01 現場司令官', '{"即断力","統率","危機対応"}', '{"指示過多","長期改善が後回し"}', '{"店長","時間帯責任者"}', '{"繁盛店","大型店"}', '{"店長","店舗責任者"}', 'Guest', 'Business', 'Mass', 'Leader', 'Arrange', 'Intuitive', '/characters/T29.webp', 'ピークタイムの5分間にこそ、その店の本当の実力が出ると考えるタイプです。繁忙時ほど頭が冴え、全体を見渡して即座に判断を下せます。満席の店内でも、誰が何をすべきか瞬時に見えているという、卓越した状況把握力を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('75f8d8dd-65ba-5357-9052-a36b955caa0a', 'T30', 'チェーン統括官', '一店舗の成功を、百店舗の標準へ。', 'あなたは、一店舗の成功をたまたまの奇跡で終わらせず、百店舗で再現できる標準へと落とし込むことに使命感を持つタイプです。マニュアルや教育、数値管理を丁寧に整え、優れた店舗の運営を見ると、すぐマニュアル化したくなります。どの店舗でも同じ品質が出せていることに、何よりの安心を感じる、仕組みづくりの達人です。', 'Scale Builders', 'C04 再現の達人', '{"標準化","多店舗管理","教育"}', '{"硬直化","個店の個性を失う"}', '{"SV","運営統括","教育責任者"}', '{"チェーン"}', '{"統括部長","SV"}', 'Guest', 'Business', 'Mass', 'Leader', 'Arrange', 'Data', '/characters/T30.webp', '一店舗の成功をたまたまで終わらせず、百店舗で再現できる標準へ落とし込むことに使命感を持つタイプです。マニュアルや教育、数値管理を丁寧に整えます。優れた店舗の運営を見ると、すぐマニュアル化したくなるほど、仕組みへの落とし込みが自然な思考の癖になっています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('969f4ff2-93e2-5653-b067-64a058bd6b99', 'T31', 'FC帝王', '勝てる店の型を、オーナーと全国へ。', 'あなたは、勝てる店の型を作り上げ、それをオーナーとともに全国へ広げていくことに情熱を燃やすタイプです。事業拡大への強い意欲と交渉力を持ち、強い業態モデルを見ると『これは広げられる』とすぐに考えます。出店数が増えるたびに手応えを感じる、事業拡大の帝王です。', 'Scale Builders', 'B02 未来のオーナー', '{"事業拡大","オーナー支援","交渉力"}', '{"拡大優先","加盟店との摩擦"}', '{"FC本部","加盟開発"}', '{"FC業態"}', '{"FC責任者","事業責任者"}', 'Guest', 'Business', 'Mass', 'Leader', 'Venture', 'Intuitive', '/characters/T31.webp', '勝てる店の型を作り上げ、それをオーナーとともに全国へ広げていくことに情熱を燃やすタイプです。事業拡大への強い意欲と交渉力を持ちます。強い業態モデルを見ると『これは広げられる』とすぐに考えるほど、事業のスケール可能性を見抜く目に長けています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('47b75aab-2b2d-5eae-8a8c-b44c574a73a8', 'T32', '多店舗展開の覇者', '店を増やしても、利益と品質を落とさない。', 'あなたは、店舗数を増やしながらも、利益と品質を落とさないことにこだわる、統合思考の持ち主です。出店戦略、人材、資金、KPIを一つの絵として捉え、出店計画を立てるときには人材と資金の両方を同時に考えています。経営指標が全体としてどう動いているかを俯瞰するのが好きな、多店舗展開の覇者です。', 'Scale Builders', 'L05 繁盛店メーカー', '{"拡大力","組織設計","収益管理"}', '{"現場の疲弊","成長速度の過信"}', '{"事業部長","COO","出店責任者"}', '{"チェーン","複数ブランド"}', '{"COO","事業本部長"}', 'Guest', 'Business', 'Mass', 'Leader', 'Venture', 'Data', '/characters/T32.webp', '店舗数を増やしながらも、利益と品質を落とさないことにこだわる統合思考の持ち主です。出店戦略、人材、資金、KPIを一つの絵として捉えます。店舗数が増えても、品質のブレがないか気になるほど、拡大と品質維持の両立に強いこだわりを持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('3904b690-00cb-58ee-ae4d-60f0332dd8af', 'T33', '火入れの魔術師', '一秒、一度の差で、完成を決める。', 'あなたは、火加減という誰もが軽視しがちな一瞬に、料理の完成度がすべて宿ると信じている職人気質の持ち主です。素材と対話するように熱を入れ、言葉よりも手先の感覚で状況を判断します。炭火や鉄板の音と色だけで、火加減の答えが分かる。難しい素材ほど燃える、感覚と集中力の魔術師です。', 'Culinary Artists', 'C01 火入れの魔術師', '{"技術精度","集中力","感覚"}', '{"感覚依存","他者への共有が難しい"}', '{"焼き手","肉料理人","鉄板焼"}', '{"焼鳥","焼肉","フレンチ"}', '{"スペシャリスト","料理長候補"}', 'Product', 'Craft', 'High-end', 'Specialist', 'Arrange', 'Intuitive', '/characters/T33.webp', '火加減という誰もが軽視しがちな一瞬に、料理の完成度がすべて宿ると信じているタイプです。素材と対話するように熱を入れ、言葉より手先の感覚で状況を判断します。難しい素材ほど燃える職人気質で、同じ素材でも、その日の状態を見て焼き方を微調整する繊細さを持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('ceb30b18-22cb-57d3-8c03-369a733e28fb', 'T34', '料理研究者', 'おいしさを、理論と検証で解き明かす。', 'あなたは、『おいしい』という感覚を、偶然ではなく理論として解き明かしたいと考えるタイプです。試作と計測を繰り返し、感覚を誰もが再現できる知識に変換することに知的な喜びを感じます。同じ料理を何十回も試作して、微差にこだわる。味の再現性が取れた瞬間、達成感で満たされる研究者気質です。', 'Culinary Artists', 'C02 味覚の探究者', '{"研究力","分析","改善"}', '{"完成が遅い","顧客ニーズとのずれ"}', '{"R&D","商品開発","品質管理"}', '{"メーカー","ラボ","高級店"}', '{"研究担当","開発責任者"}', 'Product', 'Craft', 'High-end', 'Specialist', 'Arrange', 'Data', '/characters/T34.webp', '『おいしい』という感覚を、偶然ではなく理論として解き明かしたいと考えるタイプです。試作と計測を繰り返し、感覚を誰もが再現できる知識に変換することに知的な喜びを感じます。『なぜおいしいのか』を成分や工程で説明したくなるほど、感覚を言語化・数値化することへの強い探究心を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('fe9ef2bc-e418-5ef5-bd4e-70c30ccbae17', 'T35', '孤高の革新シェフ', '常識の外側に、次の一皿がある。', 'あなたは、既存の料理の枠に収まることを窮屈に感じ、自分だけの表現を追い求めるタイプです。常識や前例よりも、自分の感性が『次に来る』と告げるものを信じて突き進みます。『こんな料理、見たことない』と言われると心が躍る。一皿の盛り付けに、何時間でも向き合える、孤高の表現者です。', 'Culinary Artists', 'C03 一皿の芸術家', '{"独創性","表現力","挑戦"}', '{"独善的になりやすい","再現性不足"}', '{"シェフ","クリエイター"}', '{"ガストロノミー","創作料理"}', '{"料理長","オーナーシェフ候補"}', 'Product', 'Craft', 'High-end', 'Specialist', 'Venture', 'Intuitive', '/characters/T35.webp', '既存の料理の枠に収まることを窮屈に感じ、自分だけの表現を追い求めるタイプです。常識や前例よりも、自分の感性が『次に来る』と告げるものを信じて突き進みます。既存のレシピ通りに作ることに退屈さを感じるほど、独自の表現への渇望が強い性質を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('fd25aa3e-d829-59a6-909d-a207d2aa2ce6', 'T36', 'ガストロノミー開発者', '感性と科学を、忘れられない体験に。', 'あなたは、感性だけに頼らず、調理科学とデータを駆使して忘れられない食体験を設計しようとするタイプです。感覚と理論、両方の言語を使いこなす稀有な存在です。調理科学の論文や技法書を読むのが純粋に楽しい。『この温度と圧力なら、こういう食感になる』が計算できる、科学するシェフです。', 'Culinary Artists', 'C02 味覚の探究者', '{"科学的思考","創造性","精密さ"}', '{"設備・コスト負担","難解になりやすい"}', '{"研究シェフ","商品開発"}', '{"ガストロノミー","高級ホテル"}', '{"開発シェフ","R&D責任者"}', 'Product', 'Craft', 'High-end', 'Specialist', 'Venture', 'Data', '/characters/T36.webp', '感性だけに頼らず、調理科学とデータを駆使して忘れられない食体験を設計しようとするタイプです。感覚と理論、両方の言語を使いこなす稀有な存在です。感性で生まれたアイデアを、理論で裏付けたくなるほど、直感と科学的検証を両輪で回すスタイルを持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('9bf2d281-21b9-5bcf-afa4-1037eb019778', 'T37', '伝説の料理長', '腕だけでなく、人と厨房を育てる。', 'あなたは、自分の腕を極めるだけでなく、その技術と基準を厨房全体、そして次の世代へ伝えることに責任感を持つタイプです。技術者でありながら、育てる人でもあります。自分の技術より、育てたスタッフの成長に誇りを感じる。後輩が独り立ちする瞬間が、何より感慨深い、伝説の料理長です。', 'Culinary Artists', 'L02 育成マイスター', '{"技術","育成","統率"}', '{"高基準の圧力","後継育成に時間"}', '{"料理長","総料理長"}', '{"高級店","ホテル"}', '{"料理長","総料理長"}', 'Product', 'Craft', 'High-end', 'Leader', 'Arrange', 'Intuitive', '/characters/T37.webp', '自分の腕を極めるだけでなく、その技術と基準を厨房全体、そして次の世代へ伝えることに責任感を持つタイプです。技術者でありながら、育てる人でもあります。厨房に入った瞬間、乱れている箇所にすぐ気づくほど、高い基準を厨房全体に対して持ち続けています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('d7691d1d-452f-5357-a35b-89ecf681a816', 'T38', '厨房品質統括官', '名店の味を、どの店舗でも。', 'あなたは、名店の味を一つの厨房だけの奇跡で終わらせず、どの店舗でも再現できる仕組みに変えることに使命感を持つタイプです。感覚を工程とレシピに落とし込む翻訳者的な役割を担います。どの店舗で食べても同じ味かどうか、つい確認したくなる。新人でも一定の品質が出せる仕組みができると安心する、品質統括の要です。', 'Culinary Artists', 'C04 再現の達人', '{"品質管理","標準化","教育"}', '{"創造性を抑えやすい","現場反発"}', '{"品質統括","セントラルキッチン責任者"}', '{"高級チェーン","ホテル"}', '{"品質責任者","統括料理長"}', 'Product', 'Craft', 'High-end', 'Leader', 'Arrange', 'Data', '/characters/T38.webp', '名店の味を、一つの厨房だけの奇跡で終わらせず、どの店舗でも再現できる仕組みに変えることに使命感を持つタイプです。感覚を工程とレシピに落とし込む翻訳者的な役割を担います。レシピの工程を見ると、あいまいな表現を数値化したくなるほど、曖昧さを排除することへの強いこだわりを持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('a75397f4-5140-5737-97d9-f0989572db2d', 'T39', '料理界の開拓者', '知らない土地で、新しい食の旗を立てる。', 'あなたは、見知らぬ土地であっても、自分の技術と感性を武器に新しい食の旗を立てられるタイプです。文化の違いを恐れるより、適応しながら挑戦することに燃える開拓者気質です。海外の見知らぬ食材を見ると、まず試してみたくなる。『前例がない市場』と聞くとむしろやる気が出る、料理界の開拓者です。', 'Culinary Artists', 'G02 世界への挑戦者', '{"越境力","技術","適応"}', '{"文化理解不足","運営基盤の弱さ"}', '{"海外シェフ","新店立ち上げ"}', '{"海外店","新業態"}', '{"立ち上げ料理長","ブランドシェフ"}', 'Product', 'Craft', 'High-end', 'Leader', 'Venture', 'Intuitive', '/characters/T39.webp', '見知らぬ土地であっても、自分の技術と感性を武器に新しい食の旗を立てられるタイプです。文化の違いを恐れるより、適応しながら挑戦することに燃える開拓者気質です。現地の食文化と自分の技術を掛け合わせるのが楽しいと感じるほど、異文化との融合に強い喜びを見出します。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('ff618a0a-a971-595d-94ce-d5b63520e406', 'T40', 'シェフプロデューサー', '一皿から、ブランドと事業を生み出す。', 'あなたは、一皿の魅力を料理そのものにとどめず、商品・空間・発信・複数店舗へと広げていく、経営者気質のシェフです。料理人でありながら、事業家としての視座も持っています。一皿のアイデアを見ると、すぐ商品化や店舗展開を考えてしまう。厨房よりも、ブランド全体の物語を描くことに燃える瞬間がある、シェフプロデューサーです。', 'Culinary Artists', 'B01 ブランド創造者', '{"ブランド力","経営視点","創造性"}', '{"現場時間の減少","個人依存"}', '{"シェフプロデューサー","ブランド監修"}', '{"高級ブランド","複数業態"}', '{"代表シェフ","プロデューサー"}', 'Product', 'Craft', 'High-end', 'Leader', 'Venture', 'Data', '/characters/T40.webp', '一皿の魅力を、料理そのものにとどめず、商品・空間・発信・複数店舗へと広げていく経営者気質のシェフです。料理人でありながら、事業家としての視座も持ちます。自分の料理がメディアやSNSでどう語られるか気になるほど、料理を「事業の資産」として捉える視点を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('8543b941-cb0a-5911-9614-30f176d2ec3f', 'T41', '町中華の職人', '毎日食べたい味を、今日も強く出す。', 'あなたは、特別な日ではなく、毎日の食卓にこそ本当の勝負があると考えるタイプです。派手さより、今日も変わらぬ美味しさを出し続けることに職人としての誇りを持ちます。中華鍋を振る音とタイミングだけで火加減を合わせられる。行列ができても、リズムを崩さず淡々とさばき続ける、町中華の職人です。', 'Food Craftsmen', 'C01 火入れの魔術師', '{"スピード","安定品質","体力"}', '{"属人化","改善時間不足"}', '{"中華料理人","大衆調理"}', '{"町中華","食堂"}', '{"調理リーダー"}', 'Product', 'Craft', 'Mass', 'Specialist', 'Arrange', 'Intuitive', '/characters/T41.webp', '特別な日ではなく、毎日の食卓にこそ本当の勝負があると考えるタイプです。派手さより、今日も変わらぬ美味しさを出し続けることに職人としての誇りを持ちます。『いつもの味』が出せていることに一番の安心を感じるほど、日常の安定こそが最大の価値だと理解しています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('b656d19e-24fb-5887-83b5-9943a5c392e7', 'T42', '調理オペレーション研究者', '速さと品質は、両立できる。', 'あなたは、『速さ』と『品質』は本来トレードオフではないと信じ、工程そのものを設計し直すことに面白さを感じるタイプです。感覚ではなく分析で厨房のムダを見つけます。厨房の動線を見ると、つい頭の中で配置換えを始めてしまう。大量調理でも品質のブレがないことに達成感を覚える、調理オペレーションの研究者です。', 'Food Craftsmen', 'C04 再現の達人', '{"工程設計","分析","再現性"}', '{"現場の創意を抑える","最適化過多"}', '{"生産管理","オペレーション開発"}', '{"給食","セントラルキッチン","チェーン"}', '{"工程責任者","生産管理"}', 'Product', 'Craft', 'Mass', 'Specialist', 'Arrange', 'Data', '/characters/T42.webp', '『速さ』と『品質』は本来トレードオフではないと信じ、工程そのものを設計し直すことに面白さを感じるタイプです。感覚ではなく分析で厨房のムダを見つけます。『この工程、一手減らせるのでは』が口癖になるほど、常に効率化の視点で現場を見つめています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('41c0ac73-d15c-5373-bad6-a5f8c3174e9f', 'T43', '屋台の発明家', '小さな場所から、大きな話題を。', 'あなたは、限られた設備や予算をハンデと捉えず、アイデアと勢いで乗り越えることに燃えるタイプです。小さな場所からでも大きな話題を生み出せると信じています。『これ、屋台で出したら絶対売れる』が頭に浮かぶとすぐ試したくなる。行列ができた瞬間、疲れも吹き飛ぶ、屋台の発明家です。', 'Food Craftsmen', 'C03 一皿の芸術家', '{"発想力","行動力","現場対応"}', '{"安定性不足","衛生・運営負荷"}', '{"屋台","キッチンカー","ポップアップ"}', '{"ストリートフード","イベント"}', '{"商品開発","独立候補"}', 'Product', 'Craft', 'Mass', 'Specialist', 'Venture', 'Intuitive', '/characters/T43.webp', '限られた設備や予算をハンデと捉えず、アイデアと勢いで乗り越えることに燃えるタイプです。小さな場所からでも大きな話題を生み出せると信じています。限られた設備の中でどう工夫するかを考えるのが楽しいというほど、制約を逆にクリエイティビティの源にできる発想力を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('6c253a82-6d9c-54da-9b1c-956e74e1ccc5', 'T44', '大衆商品開発者', 'みんなが好きで、ちゃんと売れる味を。', 'あなたは、『みんなが好きな味』を、勘ではなくデータで設計することに知的な面白さを感じるタイプです。嗜好調査や原価計算を駆使し、ヒットする商品を組み立てます。新商品のヒット率をつい過去のデータと照らし合わせてしまう。『これは万人受けする』という直感がよく当たる、大衆商品開発者です。', 'Food Craftsmen', 'B03 新業態クリエイター', '{"商品企画","市場理解","収益性"}', '{"無難になりやすい","品質妥協"}', '{"商品開発","メーカー企画"}', '{"チェーン","食品メーカー"}', '{"商品開発責任者"}', 'Product', 'Craft', 'Mass', 'Specialist', 'Venture', 'Data', '/characters/T44.webp', '『みんなが好きな味』を、勘ではなくデータで設計することに知的な面白さを感じるタイプです。嗜好調査や原価計算を駆使し、ヒットする商品を組み立てます。原価と満足度のギリギリのラインを攻めるのが得意なほど、数字と感性の両方を武器に商品開発に向き合っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('87af9814-d065-55db-81dc-0adbcfa67188', 'T45', 'ピークタイムの神', '一番忙しい時間に、一番頼られる。', 'あなたは、一番忙しい時間こそ、自分が最も頼られる瞬間だと感じるタイプです。大量の注文が飛び交う中でも優先順位を即座に判断し、現場を止めずに回し続けます。注文が殺到するほど、逆に頭が冴えてくる。『誰が何を作っているか』が常に頭の中で見えている、ピークタイムの神です。', 'Food Craftsmen', 'L01 現場司令官', '{"瞬発力","判断力","体力"}', '{"平常時の改善を後回し","燃え尽き"}', '{"厨房リーダー","時間帯責任者"}', '{"繁盛大衆店","居酒屋"}', '{"調理責任者","店長候補"}', 'Product', 'Craft', 'Mass', 'Leader', 'Arrange', 'Intuitive', '/characters/T45.webp', '一番忙しい時間こそ、自分が最も頼られる瞬間だと感じるタイプです。大量の注文が飛び交う中でも優先順位を即座に判断し、現場を止めずに回し続けます。ピークを乗り切った後の一体感が何よりの報酬というほど、修羅場を乗り越えることに強いやりがいを見出しています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('94c441b0-2f32-569d-baf9-501c5d633f3b', 'T46', '大量調理司令官', '千食でも、同じ安全とおいしさを。', 'あなたは、一皿の味だけでなく、千食分の安全とおいしさを同時に守ることに責任感を持つタイプです。人員配置、工程、衛生管理まで含めて『現場を統括する』ことに使命感を感じます。何百食分の調理でも、衛生基準が守られているか常に気になる。大きなトラブルなく一日を終えられた時に安堵する、大量調理司令官です。', 'Food Craftsmen', 'C04 再現の達人', '{"統率","衛生管理","標準化"}', '{"柔軟性不足","管理負荷"}', '{"工場長","給食責任者","CK責任者"}', '{"給食","食品工場","CK"}', '{"現場責任者","工場長"}', 'Product', 'Craft', 'Mass', 'Leader', 'Arrange', 'Data', '/characters/T46.webp', '一皿の味だけでなく、千食分の安全とおいしさを同時に守ることに責任感を持つタイプです。人員配置、工程、衛生管理まで含めて『現場を統括する』ことに使命感を感じます。現場の人員配置を見ると、ボトルネックにすぐ気づくほど、全体を俯瞰する統率者としての視点を常に持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('54051c9e-f0b5-51cc-8e22-826d1e232069', 'T47', '大衆料理ブランド創業者', '日常の味を、全国の定番へ。', 'あなたは、特別な非日常ではなく、日常の親しみやすい味にこそブランドの可能性を見出すタイプです。現場で鍛えた商品力と独立心を武器に、自分の看板を掲げたいと考えます。『この味を全国に広げたい』という思いが常にある。自分の商品にお客様が並んでくれると心から嬉しい、大衆料理ブランド創業者です。', 'Food Craftsmen', 'B02 未来のオーナー', '{"商品力","独立心","現場感"}', '{"拡大時の品質低下","属人化"}', '{"創業者","FCオーナー"}', '{"ラーメン","中華","定食"}', '{"オーナー","ブランド代表"}', 'Product', 'Craft', 'Mass', 'Leader', 'Venture', 'Intuitive', '/characters/T47.webp', '特別な非日常ではなく、日常の親しみやすい味にこそブランドの可能性を見出すタイプです。現場で鍛えた商品力と独立心を武器に、自分の看板を掲げたいと考えます。現場に立ちながらも、次の出店先を頭の中で考えているほど、常に事業拡大への視座を持ち続けています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('93416387-210d-5f18-8b73-149c06b4357e', 'T48', '食の製造業リーダー', '料理を、強い生産システムに。', 'あなたは、料理を一皿単位ではなく、強い生産システムとして捉える経営者気質のタイプです。製造、物流、品質、コストをすべて統合的に管理し、大規模な供給を実現しようとします。生産ラインの数字を見ると、コストと品質のバランスを瞬時に計算する。『このシステムなら何十万食でも対応できる』を考えるのが好きな、食の製造業リーダーです。', 'Food Craftsmen', 'L05 繁盛店メーカー', '{"生産管理","収益管理","組織力"}', '{"現場の創造性低下","品質とコストの葛藤"}', '{"工場長","製造責任者","SCM"}', '{"食品工場","CK"}', '{"事業責任者","製造本部長"}', 'Product', 'Craft', 'Mass', 'Leader', 'Venture', 'Data', '/characters/T48.webp', '料理を一皿単位ではなく、強い生産システムとして捉える経営者気質のタイプです。製造、物流、品質、コストをすべて統合的に管理し、大規模な供給を実現しようとします。物流や在庫の最適化にひそかにやりがいを感じるほど、事業全体をシステムとして捉える視点を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('a1cea350-45e2-5e3d-a26d-f9b84dfee0e6', 'T49', '高級商品プロデューサー', '素材と物語を、選ばれる商品へ。', 'あなたは、優れた素材や職人技の裏にある物語を見抜き、それを『選ばれる商品』として編集することに喜びを感じるタイプです。単なる目利きにとどまらず、価値を伝える企画力を併せ持ちます。優れた素材に出会うと、その背景にある物語を掘り下げたくなる。パッケージや説明文の一文にまでこだわってしまう、高級商品プロデューサーです。', 'Premium Producers', 'C05 食材の目利き', '{"目利き","企画","物語化"}', '{"原価高","市場が狭い"}', '{"商品プロデューサー","バイヤー"}', '{"高級惣菜","菓子","ギフト"}', '{"商品責任者"}', 'Product', 'Business', 'High-end', 'Specialist', 'Arrange', 'Intuitive', '/characters/T49.webp', '優れた素材や職人技の裏にある物語を見抜き、それを『選ばれる商品』として編集することに喜びを感じるタイプです。単なる目利きにとどまらず、価値を伝える企画力を併せ持ちます。『これは高くても納得できる』を言葉と体験で説明できるほど、価値の伝え方に強いこだわりを持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('d41ba5f2-42de-5568-b930-2b465166bede', 'T50', 'プレミアム原価設計士', '高品質を守りながら、利益も守る。', 'あなたは、高い品質と利益、どちらも譲らずに両立させることに使命感を持つタイプです。高価な素材や複雑な工程を、感覚ではなく数字で分解して最適点を見つけ出します。高級素材を見ると、まず原価と粗利を計算してしまう。複雑な工程の中に、コスト削減の余地を見つけると嬉しい、プレミアム原価設計士です。', 'Premium Producers', 'B04 数字の戦略家', '{"原価管理","価格設計","分析"}', '{"数字偏重","現場の感性を抑える"}', '{"原価管理","商品収益管理"}', '{"高級食品","ホテル"}', '{"収益担当","管理責任者"}', 'Product', 'Business', 'High-end', 'Specialist', 'Arrange', 'Data', '/characters/T50.webp', '高い品質と利益、どちらも譲らずに両立させることに使命感を持つタイプです。高価な素材や複雑な工程を、感覚ではなく数字で分解して最適点を見つけ出します。『この価格でも十分に価値が伝わる』を数字で立証したくなるほど、感覚的な価値を論理で裏付けることに強いこだわりを持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('a4de71f6-f609-5796-bd1b-0537a65f82c1', 'T51', 'ブランドクリエイター', '商品を、持ちたくなる物語に。', 'あなたは、商品を単なるモノではなく、『持ちたくなる物語』として仕立てることに情熱を注ぐタイプです。ネーミングやデザイン、世界観づくりへの感度が高いのが特徴です。商品を見ると、まずそのネーミングやパッケージのストーリーを考える。『このブランド、持っていたい』と思わせる仕掛けを考えるのが好きな、ブランドクリエイターです。', 'Premium Producers', 'B01 ブランド創造者', '{"世界観","企画","発信力"}', '{"見た目先行","現場との乖離"}', '{"ブランド企画","クリエイティブ"}', '{"菓子","酒","高級食品"}', '{"ブランドマネージャー"}', 'Product', 'Business', 'High-end', 'Specialist', 'Venture', 'Intuitive', '/characters/T51.webp', '商品を単なるモノではなく、『持ちたくなる物語』として仕立てることに情熱を注ぐタイプです。ネーミングやデザイン、世界観づくりへの感度が高いのが特徴です。世界観が伝わった瞬間の反応にやりがいを感じるほど、商品を通じて物語を届けることに強い喜びを見出しています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('c4b7d81e-ad8d-5db5-97d2-04227767b900', 'T52', 'プレミアム事業開発者', '高い価値を、新しい市場へ届ける。', 'あなたは、高い価値を持つ商品を、より広い市場に届けるための新しい道を切り拓くことに関心を持つタイプです。データと顧客理解を武器に、新しいチャネルや事業モデルを設計します。高級ブランドの新しい販路を見ると、その戦略を分析したくなる。『この商品、海外でも通用するのでは』とすぐ考える、プレミアム事業開発者です。', 'Premium Producers', 'B03 新業態クリエイター', '{"事業開発","市場分析","収益設計"}', '{"分析過多","ブランド毀損リスク"}', '{"事業開発","アライアンス"}', '{"EC","百貨店","海外"}', '{"事業開発責任者"}', 'Product', 'Business', 'High-end', 'Specialist', 'Venture', 'Data', '/characters/T52.webp', '高い価値を持つ商品を、より広い市場に届けるための新しい道を切り拓くことに関心を持つタイプです。データと顧客理解を武器に、新しいチャネルや事業モデルを設計します。市場データと顧客インサイトをすり合わせるのが得意なほど、論理的な市場理解に強みを持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('3721ae6c-5669-5f0b-b47a-e4b4ca127271', 'T53', 'ブランド統括プロデューサー', '複数の商品を、一つの憧れにまとめる。', 'あなたは、複数の商品や店舗をバラバラのままにせず、一つの『憧れ』としてまとめ上げることに使命感を持つタイプです。審美眼と統率力を併せ持ち、ブランド全体を編集します。複数の商品ラインを見ると、統一感のなさが気になってしまう。バラバラな取り組みが一つの世界観にまとまる瞬間に興奮する、ブランド統括プロデューサーです。', 'Premium Producers', 'B01 ブランド創造者', '{"統合力","審美眼","統率"}', '{"現場負荷","個別商品の弱体化"}', '{"ブランド統括","クリエイティブ責任者"}', '{"高級食品","複数ブランド"}', '{"ブランドディレクター"}', 'Product', 'Business', 'High-end', 'Leader', 'Arrange', 'Intuitive', '/characters/T53.webp', '複数の商品や店舗をバラバラのままにせず、一つの『憧れ』としてまとめ上げることに使命感を持つタイプです。審美眼と統率力を併せ持ちます。『このブランド全体で何を伝えたいか』を常に意識しているほど、個別の商品を超えたブランド全体の一貫性への強いこだわりを持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('73f5261e-d3a5-5308-8117-009d78ca7900', 'T54', 'プレミアム事業COO', '高付加価値を、強い供給体制に。', 'あなたは、高付加価値な商品を、一過性で終わらせず強い供給体制へと育てることに情熱を注ぐタイプです。品質、製造、販売、組織まで含めて事業として俯瞰します。品質・製造・販売のバランスを常に俯瞰して見ている。事業の数字が安定して伸びると、地道な積み重ねに満足感を覚える、プレミアム事業COOです。', 'Premium Producers', 'L05 繁盛店メーカー', '{"事業運営","品質管理","収益力"}', '{"管理過多","ブランドの硬直化"}', '{"COO","事業部長"}', '{"高級食品","D2C"}', '{"COO","事業本部長"}', 'Product', 'Business', 'High-end', 'Leader', 'Arrange', 'Data', '/characters/T54.webp', '高付加価値な商品を、一過性で終わらせず強い供給体制へと育てることに情熱を注ぐタイプです。品質、製造、販売、組織まで含めて事業として俯瞰します。組織が大きくなっても、ブランドの核がぶれていないか気にするほど、事業の成長と本質的な価値の両立に強いこだわりを持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('547f67e4-4dd3-5660-a2ca-4f0db0b9b52d', 'T55', '食のラグジュアリー起業家', '最高の素材と美学で、新しいブランドを。', 'あなたは、最高の素材と自分の美学を掛け合わせ、新しいブランドを世に送り出したいと考える起業家気質のタイプです。独立心と強い審美眼を武器に、自分の手でゼロから作り上げます。『こんなブランドがあったら手に取りたい』を実際に作ってしまう。素材選びから最後の一手まで、妥協せず向き合える、食のラグジュアリー起業家です。', 'Premium Producers', 'B02 未来のオーナー', '{"独立心","目利き","ブランド力"}', '{"投資負担","小規模市場"}', '{"創業者","ブランドオーナー"}', '{"酒","菓子","調味料"}', '{"創業者","CEO"}', 'Product', 'Business', 'High-end', 'Leader', 'Venture', 'Intuitive', '/characters/T55.webp', '最高の素材と自分の美学を掛け合わせ、新しいブランドを世に送り出したいと考える起業家気質のタイプです。独立心と強い審美眼を武器に、自分の手でゼロから作り上げます。自分の美学に共感してくれる顧客との出会いに深い喜びを感じるほど、感性を共有できる相手との出会いを大切にしています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('c96a2d5c-724a-5d6f-ac76-b34577db48d2', 'T56', 'プレミアムブランドCEO', '食の価値を、世界で愛される企業へ。', 'あなたは、食への憧れを一つのブランドにとどめず、世界で愛される企業へと育てたいと考える経営者気質のタイプです。ブランドポートフォリオ、資本、海外展開まで見据えた大きな視座を持ちます。一つの成功ブランドを見ると、グローバル展開の可能性を考える。海外の高級ブランド事例を研究するのが習慣になっている、プレミアムブランドCEOです。', 'Premium Producers', 'B05 食文化プロデューサー', '{"経営力","海外戦略","ブランド群管理"}', '{"拡大による希薄化","現場距離"}', '{"CEO","グループ経営"}', '{"高級食品群","海外"}', '{"CEO","代表取締役"}', 'Product', 'Business', 'High-end', 'Leader', 'Venture', 'Data', '/characters/T56.webp', '食への憧れを、一つのブランドにとどめず世界で愛される企業へと育てたいと考える経営者気質のタイプです。ブランドポートフォリオ、資本、海外展開まで見据えた大きな視座を持ちます。『このブランド群を10年後どう育てるか』を常に描いているほど、長期的かつグローバルな視座を常に持ち続けています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('6cd8be89-28f4-580d-bc8f-76f7241bab82', 'T57', '売れる味の目利き', '『おいしい』と『売れる』の交差点を見抜く。', 'あなたは、『おいしい』と『売れる』は必ずしも一致しないと知りながら、その交差点を瞬時に見抜くことに長けたタイプです。感覚と市場理解の両方を武器に、ヒットの種を素早く判断します。新商品を一口食べただけで『これは売れる』と分かる。自分の見立てが数字で証明された瞬間、密かにガッツポーズする、売れる味の目利きです。', 'Food Business Innovators', 'C05 食材の目利き', '{"目利き","市場感覚","判断力"}', '{"勘への依存","長期ブランド軽視"}', '{"バイヤー","商品選定","MD"}', '{"小売","中食","EC"}', '{"MD","商品担当"}', 'Product', 'Business', 'Mass', 'Specialist', 'Arrange', 'Intuitive', '/characters/T57.webp', '『おいしい』と『売れる』は必ずしも一致しないと知りながら、その交差点を瞬時に見抜くことに長けたタイプです。感覚と市場理解の両方を武器に、ヒットの種を素早く判断します。売場を歩くと、つい競合商品の売れ行きを観察してしまうほど、市場全体を常に観察し続けています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('22e222c3-e154-5766-bfb1-59e4d5771e5c', 'T58', 'フードデータ研究者', '食の好みを、データから読み解く。', 'あなたは、人々の『好き』という感覚を、購買データや口コミといった事実の中から読み解こうとするタイプです。感覚に頼らず、仮説と検証を繰り返して確からしさを積み上げます。購買データや口コミを見ると、隠れたパターンを探したくなる。データが自分の直感と一致した瞬間に手応えを感じる、フードデータ研究者です。', 'Food Business Innovators', 'C02 味覚の探究者', '{"分析","仮説検証","洞察"}', '{"現場感不足","データ偏重"}', '{"データ分析","リサーチ"}', '{"フードテック","メーカー"}', '{"アナリスト","研究担当"}', 'Product', 'Business', 'Mass', 'Specialist', 'Arrange', 'Data', '/characters/T58.webp', '人々の『好き』という感覚を、購買データや口コミといった事実の中から読み解こうとするタイプです。感覚に頼らず、仮説と検証を繰り返して確からしさを積み上げます。『なぜこの商品が伸びているのか』を仮説立てて検証したくなるほど、現象の裏にある理由を突き止めることに強い探究心を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('b06334dd-e958-5f14-8ec0-cc2ec31b7b63', 'T59', 'メニュー革命家', '定番の中に、次のヒットを仕込む。', 'あなたは、『定番』という言葉に安住せず、その中に次のヒットを仕込むことに喜びを感じるタイプです。既存の組み合わせや提供方法の常識を疑い、素早く新しい形を試します。定番メニューを見ると『これ、もっと面白くできる』と考えてしまう。試作したメニューが話題になった瞬間が一番の快感、メニュー革命家です。', 'Food Business Innovators', 'B03 新業態クリエイター', '{"企画力","発想","スピード"}', '{"奇抜さ優先","原価・運営軽視"}', '{"メニュー開発","クリエイター"}', '{"チェーン","中食","デリバリー"}', '{"商品企画","開発担当"}', 'Product', 'Business', 'Mass', 'Specialist', 'Venture', 'Intuitive', '/characters/T59.webp', '『定番』という言葉に安住せず、その中に次のヒットを仕込むことに喜びを感じるタイプです。既存の組み合わせや提供方法の常識を疑い、素早く新しい形を試します。異なる料理のジャンルを掛け合わせるアイデアが次々浮かぶほど、既存の枠組みを超えた発想力を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('50e62d61-c8d4-5f14-a2ce-5f5a3449527f', 'T60', 'フードテック開発者', '食の不便を、プロダクトで解決する。', 'あなたは、飲食現場の『不便』や『非効率』を放っておけないタイプです。テクノロジーとデータの力で、感覚的に語られがちな課題を解決可能なプロダクトへと落とし込みます。現場のムダな作業を見ると『自動化できないか』とすぐ考える。自分が作ったプロダクトで現場が楽になった瞬間に達成感を覚える、フードテック開発者です。', 'Food Business Innovators', 'G04 変革者', '{"課題発見","技術理解","事業性"}', '{"現場適合不足","開発優先"}', '{"PdM","フードテック企画","DX"}', '{"SaaS","デリバリー","ロボティクス"}', '{"PdM","事業開発"}', 'Product', 'Business', 'Mass', 'Specialist', 'Venture', 'Data', '/characters/T60.webp', '飲食現場の『不便』や『非効率』を放っておけないタイプです。テクノロジーとデータの力で、感覚的に語られがちな課題を解決可能なプロダクトへと落とし込みます。新しいPOSやロボット導入の話を聞くとワクワクするほど、テクノロジーによる現場改善の可能性に強い興味を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('526f479a-8ccf-5476-8841-7d342a7abfae', 'T61', '商品開発リーダー', 'アイデアを、売場に並ぶ商品へ。', 'あなたは、一つのアイデアを、実際に売場に並ぶ商品として完成させることに手応えを感じるタイプです。企画、試作、製造、販売という多くの工程をまとめ上げる調整力を持ちます。企画会議から発売まで、全工程を頭の中で描きながら動いている。自分が関わった商品が売場に並ぶ瞬間が一番の達成感、商品開発リーダーです。', 'Food Business Innovators', 'L04 改善プロデューサー', '{"推進力","調整力","商品理解"}', '{"調整負荷","妥協が増える"}', '{"商品開発リーダー","PM"}', '{"メーカー","チェーン"}', '{"開発責任者","PM"}', 'Product', 'Business', 'Mass', 'Leader', 'Arrange', 'Intuitive', '/characters/T61.webp', '一つのアイデアを、実際に売場に並ぶ商品として完成させることに手応えを感じるタイプです。企画、試作、製造、販売をまとめ、商品を発売まで導きます。関係部署の意見がまとまらない時、つい調整役を買って出るほど、プロジェクトを前に進めることへの強い責任感を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('c45cb78e-b9d8-560b-8034-b8072130c7cb', 'T62', '食品事業統括官', '商品・工場・営業を、一つの事業に。', 'あなたは、商品開発から製造、物流、営業まで、事業全体を一つの流れとして統括することに使命感を持つタイプです。部分最適ではなく、事業全体の成長を見据えて判断します。商品開発から営業まで、事業全体の数字を俯瞰して見ている。利益と成長、両方が伸びている瞬間に一番のやりがいを感じる、食品事業統括官です。', 'Food Business Innovators', 'L05 繁盛店メーカー', '{"事業運営","統率","収益管理"}', '{"部門間調整過多","現場距離"}', '{"事業部長","本部長"}', '{"食品メーカー","中食"}', '{"事業部長","COO"}', 'Product', 'Business', 'Mass', 'Leader', 'Arrange', 'Data', '/characters/T62.webp', '商品開発から製造、物流、営業まで、事業全体を一つの流れとして統括することに使命感を持つタイプです。部分最適ではなく、事業全体の成長を見据えて判断します。部門間の連携がうまくいくと、事業が一つにまとまった感覚を覚えるほど、組織全体の調和と成長に強い関心を持っています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('358084f4-e7dd-50fe-b9ed-0239ede5fc6d', 'T63', '飲食スタートアップ創業者', '食の大きな課題を、小さく速く解く。', 'あなたは、食にまつわる大きな課題を、大きな構想からではなく、小さく速い実験から解いていこうとするタイプです。現場の課題とテクノロジーを結びつけ、新しいサービスを生み出す行動力を持ちます。現場の課題を見ると『これはサービスにできる』とすぐ考える。初期のユーザーが喜んでくれた瞬間が何より心を支える、飲食スタートアップ創業者です。', 'Food Business Innovators', 'B02 未来のオーナー', '{"起業力","仮説検証","行動力"}', '{"資金不足","運営の複雑さ"}', '{"起業家","新規事業"}', '{"フードテック","D2C","新業態"}', '{"創業者","CEO"}', 'Product', 'Business', 'Mass', 'Leader', 'Venture', 'Intuitive', '/characters/T63.webp', '食にまつわる大きな課題を、大きな構想からではなく、小さく速い実験から解いていこうとするタイプです。現場の課題とテクノロジーを結びつけ、新しいサービスを立ち上げます。小さく試して反応を見ることに、じっとしていられない性分というほど、行動力とスピード感を何よりも大切にしています。
insert into diagnosis_types (id, type_code, name, catchcopy, description, family, primary_archetype, strengths, weaknesses, suited_jobs, suited_formats, suited_roles, tag_axis1, tag_axis2, tag_axis3, tag_axis4, tag_axis5, tag_axis6, image_url, personality_analysis, ability_analysis, growth_advice, career_path, type_moments, compatible_reason) values ('b11328e4-d810-5177-b2f2-feb2c2a492fc', 'T64', '食の革命家', '食の当たり前を変え、巨大な市場をつくる。', 'あなたは、食にまつわる『当たり前』そのものを疑い、テクノロジーと資本を使って産業構造ごと変えようとする、規格外のスケールで物事を考えるタイプです。既存の食産業の仕組みを見ると『これは変えられる』と考えてしまう。テクノロジーと資本を組み合わせた事業構想を描くのが楽しい、食の革命家です。', 'Food Business Innovators', 'G04 変革者', '{"変革力","経営力","市場創造"}', '{"構想過大","現場解像度低下"}', '{"CEO","事業創造","投資責任者"}', '{"フードテック","プラットフォーム"}', '{"CEO","代表取締役"}', 'Product', 'Business', 'Mass', 'Leader', 'Venture', 'Data', '/characters/T64.webp', '食にまつわる『当たり前』そのものを疑い、テクノロジーと資本を使って産業構造ごと変えようとする、規格外のスケールで物事を考えるタイプです。小さな実験が巨大な市場変革の兆しに見える瞬間に興奮するほど、常人とは異なるスケールで未来を見据えています。
